uint32_t resolve_src_scalar16(const amdgpu::Wavefront &wf, int ev) {
  switch (ev) {
  case 240:
    return 0x3800u; // 0.5h
  case 241:
    return 0xB800u; // -0.5h
  case 242:
    return 0x3C00u; // 1.0h
  case 243:
    return 0xBC00u; // -1.0h
  case 244:
    return 0x4000u; // 2.0h
  case 245:
    return 0xC000u; // -2.0h
  case 246:
    return 0x4400u; // 4.0h
  case 247:
    return 0xC400u; // -4.0h
  case 248:
    return 0x3118u; // f16 1/(2*pi)
  default:
    return resolve_src_scalar(wf, ev);
  }
}

